static void require(bool ok,const char* message){if(!ok){std::cerr<<"FAIL: "<<message<<"\n";std::exit(1);}}
static void descendants(juce::Component& c,std::vector<juce::Component*>& all){for(auto* child:c.getChildren()){all.push_back(child);descendants(*child,all);}}
static juce::Component* findNamed(juce::Component& c,const juce::String& name){std::vector<juce::Component*> all;descendants(c,all);for(auto* child:all)if(child->getName()==name)return child;return nullptr;}
