 auto route=routing.chainOrder();auto invalid=route;invalid[0]=invalid[1];require(!routing.setChainOrder(invalid)&&routing.chainOrder()==route,"duplicate route rejected atomically");invalid=route;invalid[0]=99;require(!routing.setChainOrder(invalid)&&routing.chainOrder()==route,"invalid module rejected");
 juce::MemoryBlock routingState;routing.getStateInformation(routingState);NFVocal routeRecall;routeRecall.setStateInformation(routingState.getData(),int(routingState.getSize()));require(routeRecall.chainOrder()==route,"routing survives state restore");
 auto compareRoute=[&](bool swap){NFVocal fx;fx.preset(0);fx.set("mid",12);fx.set("saturator",90);if(swap)fx.moveModule(NFVocal::Saturator,0);fx.setPlayConfigDetails(2,2,48000,256);fx.prepareToPlay(48000,256);juce::AudioBuffer<float> block(2,256);double power=0;for(int k=0;k<200;++k){for(int c=0;c<2;++c)for(int i=0;i<256;++i)block.setSample(c,i,.15f*std::sin(juce::MathConstants<float>::twoPi*1200*float(k*256+i)/48000));fx.processBlock(block,midi);if(k>100)for(int i=0;i<256;++i)power+=block.getSample(0,i)*block.getSample(0,i);}return power;};
 double before=compareRoute(false),after=compareRoute(true);require(std::abs(before-after)>before*.2,"reordering changes actual DSP, not only graphics");
 // Aggression: measure third harmonic against the old soft saturation transfer.
 {NFVocal fx;fx.preset(0);fx.set("saturator",100);fx.setPlayConfigDetails(2,2,48000,256);fx.prepareToPlay(48000,256);juce::AudioBuffer<float> block(2,256);double fundamental=0,third=0,oldFundamental=0,oldThird=0;for(int k=0;k<300;++k){for(int c=0;c<2;++c)for(int i=0;i<256;++i)block.setSample(c,i,.15f*std::sin(juce::MathConstants<float>::twoPi*1000*float(k*256+i)/48000));fx.processBlock(block,midi);if(k>=150)for(int i=0;i<256;++i){double phase=juce::MathConstants<double>::twoPi*1000*double(k*256+i)/48000;double old=std::tanh(.15*std::sin(phase)*6)/std::sqrt(6.);fundamental+=block.getSample(0,i)*std::sin(phase);third+=block.getSample(0,i)*std::sin(phase*3);oldFundamental+=old*std::sin(phase);oldThird+=old*std::sin(phase*3);}}require(std::abs(third/fundamental)>.15&&std::abs(third/fundamental)>2*std::abs(oldThird/oldFundamental),"new saturation has materially stronger harmonics");}
