 auto* midSlider=dynamic_cast<juce::Slider*>(findNamed(*e,"mid"));require(midSlider&&midSlider->getSliderStyle()==juce::Slider::LinearVertical,"Mid is a fader");require(findNamed(*e,"midMode")&&findNamed(*e,"midOn"),"Mid has mode and on/off");
