 auto* handle=findNamed(*e,"move-gate");auto* pitchCard=findNamed(*e,"module-pitch");require(handle&&pitchCard,"drag handles exist");auto time=juce::Time::getCurrentTime();juce::Point<float> pressPoint(35,16);auto targetScreen=pitchCard->localPointToGlobal(juce::Point<int>(pitchCard->getWidth()-4,16));auto targetPoint=handle->getLocalPoint(nullptr,targetScreen).toFloat();
 juce::ModifierKeys held(juce::ModifierKeys::leftButtonModifier);juce::MouseEvent press(juce::Desktop::getInstance().getMainMouseSource(),pressPoint,held,1,0,0,0,0,handle,handle,time,pressPoint,time,1,false);juce::MouseEvent drag(juce::Desktop::getInstance().getMainMouseSource(),targetPoint,held,1,0,0,0,0,handle,handle,time,pressPoint,time,1,true);handle->mouseDown(press);handle->mouseDrag(drag);handle->mouseUp(drag);require(p.chainOrder()[7]==NFVocal::Gate,"UI drag changes route across rows after Pitch");
