 feedMeter();require(p.reduction.load()>1,"gain reduction meter receives actual compression");p.set("compressOn",0);feedMeter();require(p.reduction.load()==0,"gain reduction meter clears when compressor disabled");p.set("compressOn",1);feedMeter();CFRunLoopRunInMode(kCFRunLoopDefaultMode,.08,false);
