 for(int end=0;end<2;++end){for(auto id:{"input","bass","treble","compress","reverb","delay","pitch","output"})p.set(id,(juce::String(id)=="input"||juce::String(id)=="output")?(end?24.f:-24.f):(end?10.f:-10.f));CFRunLoopRunInMode(kCFRunLoopDefaultMode,.03,false);auto extreme=e->createComponentSnapshot(e->getLocalBounds(),true,2.f);auto path=juce::File(argv[1]).getSiblingFile(end?"NF-Vocal-1.2.0-Max.png":"NF-Vocal-1.2.0-Min.png");path.deleteFile();juce::FileOutputStream file(path);require(png.writeImageToStream(extreme,file),"fader extremes screenshot");}
